begin;
select no_plan();
select ok(not has_table_privilege(r,'workspace_private.'||d||t,p),r||' cannot '||p||' '||d||t)
from unnest(array['anon','authenticated'])r cross join unnest(array['ministry','nonprofit','investor','executive'])d
cross join unnest(array['_editor_drafts','_editor_draft_receipts'])t cross join unnest(array['select','insert','update','delete'])p;
select ok((select relrowsecurity from pg_class where oid=('workspace_private.'||d||t)::regclass),d||t||' has RLS')
from unnest(array['ministry','nonprofit','investor','executive'])d cross join unnest(array['_editor_drafts','_editor_draft_receipts'])t;
select ok(not has_function_privilege(r,s,'execute'),r||' cannot invoke '||s)
from unnest(array['anon','authenticated'])r cross join unnest(array['workspace_private.editor_recovery_schema(text,text)',
'workspace_private.editor_recovery_validate(jsonb,jsonb,integer)','workspace_private.require_editor_target(jsonb)',
'workspace_private.editor_source_revision(uuid,jsonb)','workspace_private.editor_draft_snapshot(uuid,jsonb)'])s;
select ok(not has_function_privilege('anon',s,'execute'),'anonymous cannot invoke '||s)
from unnest(array['workspace.native_editor_draft(jsonb)','workspace.native_change_editor_draft(jsonb)'])s;
