select '15aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','15111111-1111-4111-8111-111111111111',b,'operator_assignment','p15-owner-'||b
from unnest(array['ministry','nonprofit_founder','investor','executive'])b;
